"use client"

import {
  ColorPicker as ColorPickerPrimitive,
  ColorPickerArea as ColorPickerAreaPrimitive,
  ColorPickerAreaCanvas as ColorPickerAreaCanvasPrimitive,
  ColorPickerAreaThumb as ColorPickerAreaThumbPrimitive,
  ColorPickerChannelInput as ColorPickerChannelInputPrimitive,
  ColorPickerEyeDropper as ColorPickerEyeDropperPrimitive,
  ColorPickerInput as ColorPickerInputPrimitive,
  ColorPickerSlider as ColorPickerSliderPrimitive,
  ColorPickerSliderThumb as ColorPickerSliderThumbPrimitive,
  ColorPickerSwatch as ColorPickerSwatchPrimitive,
  ColorPickerSwatches as ColorPickerSwatchesPrimitive,
  ColorPickerSwatchItem as ColorPickerSwatchItemPrimitive,
  createColorPickerController,
  type ColorChannel,
  type ColorPickerState,
} from "@ui-sdk/react/color-picker"
import {
  createContext,
  use,
  useMemo,
  useRef,
  useState,
  type ComponentProps,
  type KeyboardEvent,
  type PointerEvent,
  type ReactNode,
} from "react"
import { PipetteIcon } from "lucide-react"

import { fieldSurfaceClassName } from "@/components/ui/input"
import { ControlTooltip, type ControlTooltipOption } from "@/components/ui/tooltip"
import { useColorAreaCanvas } from "@/components/ui/use-color-area-canvas"
import { useHeldColor, type Ending } from "@/components/ui/use-held-color"
import type { AreaGamut } from "@/lib/oklch-gamut"
import { cnState } from "@/lib/utils"

type ColorPickerLabels = {
  /** Names the text field that takes any CSS colour. */
  value: string
}

const colorPickerLabels: ColorPickerLabels = { value: "Colour value" }

const GamutContext = createContext<AreaGamut>("srgb")
// The area's state, inside an OKLCH area across chroma and up lightness: the one ColorPickerAreaCanvas paints itself.
const OklchAreaContext = createContext<ColorPickerState | null>(null)

// Where the picker and its thumbs report a lifted pointer or a key, before UI SDK commits the colour.
const EndingContext = createContext<(ending: Ending) => void>(() => {})
const AreaAxesContext = createContext<{ x: ColorChannel; y: ColorChannel }>({
  x: "chroma",
  y: "lightness",
})

const isRtl = (element: Element) => getComputedStyle(element).direction === "rtl"
const keyOf = (event: KeyboardEvent<HTMLElement>) => ({
  key: event.key,
  shift: event.shiftKey,
  rtl: isRtl(event.currentTarget),
})

type ReleaseHandlers = Pick<ComponentProps<"div">, "onPointerUpCapture" | "onPointerCancelCapture">

type ColorPickerProps = ComponentProps<typeof ColorPickerPrimitive> & {
  labels?: Partial<ColorPickerLabels>
}

function HeldColor({ children, ...options }: Parameters<typeof useHeldColor>[0] & { children: ReactNode }) {
  const recordEnding = useHeldColor(options)
  return <EndingContext value={recordEnding}>{children}</EndingContext>
}

/**
 * A group around the parts. Without children it renders an area, a hue slider, a swatch and a text field; with
 * `space="oklch"` the area paints itself on a canvas, since no gradient draws OKLCH's edge. A thumb dragged past the
 * gamut's edge stays where it was let go, and the value is the closest colour inside the gamut.
 */
function ColorPicker({ className, children, labels, controller, ...props }: ColorPickerProps) {
  const [ownController] = useState(createColorPickerController)
  const picker = controller ?? ownController
  const oklch = props.space === "oklch"
  const content = children ?? (
    <>
      <ColorPickerArea>
        {oklch ? <ColorPickerAreaCanvas /> : null}
        <ColorPickerAreaThumb />
      </ColorPickerArea>
      <ColorPickerSlider channel="hue">
        <ColorPickerSliderThumb />
      </ColorPickerSlider>
      <div className="flex items-center gap-items">
        <ColorPickerSwatch />
        <ColorPickerInput aria-label={labels?.value ?? colorPickerLabels.value} />
      </div>
    </>
  )
  return (
    <GamutContext value={props.gamut === "p3" ? "p3" : "srgb"}>
      <ColorPickerPrimitive
        className={cnState("flex w-full flex-col gap-items", className)}
        controller={picker}
        {...props}
      >
        {(state: ColorPickerState) => (
          <HeldColor color={state.color} space={props.space} gamut={props.gamut} controller={picker}>
            {typeof content === "function" ? content(state) : content}
          </HeldColor>
        )}
      </ColorPickerPrimitive>
    </GamutContext>
  )
}

type Fractions = Partial<Record<ColorChannel, number>>

// UI SDK ends a drag on the document's pointerup, after the captured pointer's own lifts through the area or slider.
function useReleaseHandlers(
  { onPointerUpCapture, onPointerCancelCapture }: ReleaseHandlers,
  fractions: (event: PointerEvent<HTMLDivElement>, rect: DOMRect) => Fractions,
): ReleaseHandlers {
  const recordEnding = use(EndingContext)
  const release = (event: PointerEvent<HTMLDivElement>) =>
    recordEnding({ release: fractions(event, event.currentTarget.getBoundingClientRect()) })
  return {
    onPointerUpCapture: (event) => {
      release(event)
      onPointerUpCapture?.(event)
    },
    onPointerCancelCapture: (event) => {
      release(event)
      onPointerCancelCapture?.(event)
    },
  }
}

const across = (event: PointerEvent<HTMLDivElement>, rect: DOMRect) => {
  const fraction = rect.width ? (event.clientX - rect.left) / rect.width : 0
  return isRtl(event.currentTarget) ? 1 - fraction : fraction
}
const up = (event: PointerEvent<HTMLDivElement>, rect: DOMRect) =>
  rect.height ? (rect.bottom - event.clientY) / rect.height : 0

function ColorPickerArea({
  className,
  children,
  x,
  y,
  onPointerUpCapture,
  onPointerCancelCapture,
  ...props
}: ComponentProps<typeof ColorPickerAreaPrimitive>) {
  const axes = useMemo(() => ({ x: x ?? "chroma", y: y ?? "lightness" }), [x, y])
  const release = useReleaseHandlers({ onPointerUpCapture, onPointerCancelCapture }, (event, rect) => ({
    [axes.x]: across(event, rect),
    [axes.y]: up(event, rect),
  }))
  const chromaByLightness = axes.x === "chroma" && axes.y === "lightness"
  return (
    <AreaAxesContext value={axes}>
      <ColorPickerAreaPrimitive
        x={x}
        y={y}
        {...release}
        className={cnState(
          "relative h-36 w-full shrink-0 touch-none rounded-choice border bg-(--color-area-background) has-[canvas]:bg-muted data-disabled:opacity-50",
          className,
        )}
        {...props}
      >
        {(state: ColorPickerState) => (
          <OklchAreaContext value={state.space === "oklch" && chromaByLightness ? state : null}>
            {typeof children === "function" ? children(state) : children}
          </OklchAreaContext>
        )}
      </ColorPickerAreaPrimitive>
    </AreaAxesContext>
  )
}

const canvasClassName = "pointer-events-none absolute inset-0 size-full rounded-choice"

/**
 * Paints the area pixel by pixel. In an OKLCH area across chroma and up lightness, a point past the gamut's edge
 * shows the colour the picker holds there (the same lightness and hue at the most chroma the gamut allows), so the
 * whole box is colour and the thumb always sits on the colour chosen. Other channels use UI SDK's canvas.
 */
function ColorPickerAreaCanvas({ className, ...props }: ComponentProps<typeof ColorPickerAreaCanvasPrimitive>) {
  const area = use(OklchAreaContext)
  const gamut = use(GamutContext)
  const canvas = useRef<HTMLCanvasElement>(null)
  useColorAreaCanvas(area ? canvas : null, area?.color.coords[2] ?? 0, gamut)
  const classes = cnState(canvasClassName, className)
  if (!area) return <ColorPickerAreaCanvasPrimitive className={classes} {...props} />
  return (
    <canvas
      ref={canvas}
      aria-hidden="true"
      data-slot="color-picker-area-canvas"
      // UI SDK places the thumb from the inline start, so the canvas mirrors with it in right to left.
      className={`${typeof classes === "function" ? classes(area) : classes} rtl:-scale-x-100`}
    />
  )
}

const thumbClassName =
  "touch-target size-4 rounded-full border-2 border-background bg-(--color-picker-color) shadow-sm ring-1 ring-foreground/50 outline-none focus-visible:ring-3 focus-visible:ring-ring data-disabled:cursor-not-allowed"

function ColorPickerAreaThumb({
  className,
  onKeyDownCapture,
  ...props
}: ComponentProps<typeof ColorPickerAreaThumbPrimitive>) {
  const recordEnding = use(EndingContext)
  const axes = use(AreaAxesContext)
  return (
    <ColorPickerAreaThumbPrimitive
      className={cnState(`${thumbClassName} -translate-x-1/2 -translate-y-1/2`, className)}
      onKeyDownCapture={(event) => {
        recordEnding({ ...keyOf(event), ...axes })
        onKeyDownCapture?.(event)
      }}
      {...props}
    />
  )
}

function ColorPickerSlider({
  className,
  onPointerUpCapture,
  onPointerCancelCapture,
  ...props
}: ComponentProps<typeof ColorPickerSliderPrimitive>) {
  const release = useReleaseHandlers({ onPointerUpCapture, onPointerCancelCapture }, (event, rect) => {
    const { channel, orientation } = event.currentTarget.dataset
    if (!channel) return {}
    return { [channel]: orientation === "vertical" ? up(event, rect) : across(event, rect) }
  })
  return (
    <ColorPickerSliderPrimitive
      {...release}
      className={cnState(
        "relative h-3 w-full shrink-0 touch-none rounded-full border border-input bg-(--color-slider-background) data-disabled:opacity-50 data-[orientation=vertical]:h-36 data-[orientation=vertical]:w-3",
        className,
      )}
      {...props}
    />
  )
}

function ColorPickerSliderThumb({
  className,
  onKeyDownCapture,
  ...props
}: ComponentProps<typeof ColorPickerSliderThumbPrimitive>) {
  const recordEnding = use(EndingContext)
  return (
    <ColorPickerSliderThumbPrimitive
      onKeyDownCapture={(event) => {
        const channel = event.currentTarget.dataset.channel
        if (channel) recordEnding({ ...keyOf(event), channel: channel as ColorChannel })
        onKeyDownCapture?.(event)
      }}
      className={cnState(
        `${thumbClassName} top-1/2 -translate-x-1/2 -translate-y-1/2 data-[orientation=vertical]:start-1/2 data-[orientation=vertical]:top-auto data-[orientation=vertical]:translate-y-1/2 rtl:translate-x-1/2`,
        className,
      )}
      {...props}
    />
  )
}

function ColorPickerSwatch({ className, ...props }: ComponentProps<typeof ColorPickerSwatchPrimitive>) {
  return (
    <ColorPickerSwatchPrimitive
      className={cnState(
        "size-control shrink-0 rounded-choice border border-input-strong bg-(--color-picker-color)",
        className,
      )}
      {...props}
    />
  )
}

const textFieldClassName = `${fieldSurfaceClassName} h-field-control min-w-0 rounded-control px-control-x text-entry outline-none focus-visible:ring-2 focus-visible:ring-ring data-readonly:bg-muted`

function ColorPickerInput({ className, ...props }: ComponentProps<typeof ColorPickerInputPrimitive>) {
  return (
    <ColorPickerInputPrimitive
      className={cnState(`${textFieldClassName} w-full font-mono`, className)}
      spellCheck={false}
      {...props}
    />
  )
}

function ColorPickerChannelInput({ className, ...props }: ComponentProps<typeof ColorPickerChannelInputPrimitive>) {
  return (
    <ColorPickerChannelInputPrimitive
      className={cnState(`${textFieldClassName} w-16 text-center tabular-nums`, className)}
      {...props}
    />
  )
}

function ColorPickerEyeDropper({
  className,
  children,
  "aria-label": ariaLabel = "Pick a colour from the screen",
  tooltip,
  ...props
}: ComponentProps<typeof ColorPickerEyeDropperPrimitive> & {
  tooltip?: ControlTooltipOption
}) {
  return (
    <ControlTooltip label={ariaLabel} tooltip={tooltip} iconOnly={children === undefined}>
      <ColorPickerEyeDropperPrimitive
        aria-label={ariaLabel}
        className={cnState(
          `${fieldSurfaceClassName} touch-target inline-flex size-control shrink-0 cursor-pointer items-center justify-center rounded-control text-muted-foreground outline-none hover:bg-accent hover:text-accent-foreground focus-visible:ring-2 focus-visible:ring-ring data-unsupported:hidden [&_svg]:size-4`,
          className,
        )}
        {...props}
      >
        {children ?? <PipetteIcon />}
      </ColorPickerEyeDropperPrimitive>
    </ControlTooltip>
  )
}

function ColorPickerSwatches({ className, ...props }: ComponentProps<typeof ColorPickerSwatchesPrimitive>) {
  return <ColorPickerSwatchesPrimitive className={cnState("flex flex-wrap gap-inline", className)} {...props} />
}

// On a coarse pointer the presets grow to 44px rather than overlapping hit areas, since they sit a gap apart.
function ColorPickerSwatchItem({ className, ...props }: ComponentProps<typeof ColorPickerSwatchItemPrimitive>) {
  return (
    <ColorPickerSwatchItemPrimitive
      className={cnState(
        "size-control-sm shrink-0 cursor-pointer rounded-choice border border-input-strong bg-(--color-picker-color) outline-none pointer-coarse:size-(--control-height-touch) focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background data-disabled:cursor-not-allowed data-selected:ring-2 data-selected:ring-foreground data-selected:ring-offset-2 data-selected:ring-offset-background",
        className,
      )}
      {...props}
    />
  )
}

export {
  ColorPicker,
  ColorPickerArea,
  ColorPickerAreaCanvas,
  ColorPickerAreaThumb,
  ColorPickerChannelInput,
  ColorPickerEyeDropper,
  ColorPickerInput,
  ColorPickerSlider,
  ColorPickerSliderThumb,
  ColorPickerSwatch,
  ColorPickerSwatches,
  ColorPickerSwatchItem,
  colorPickerLabels,
  createColorPickerController,
}
export type { ColorPickerLabels, ColorPickerProps }
export type {
  ColorChannel,
  ColorFormat,
  ColorPickerController,
  ColorPickerSpace,
  ColorPickerValueChangeReason,
} from "@ui-sdk/react/color-picker"

"use client"

import { useEffect, type RefObject } from "react"

import { paintArea, type AreaGamut } from "@/lib/oklch-gamut"

// Half the CSS size, scaled up by the browser: the area is a smooth field, and every hue step repaints it, so more
// pixels would cost time on each step for no visible gain.
function paint(canvas: HTMLCanvasElement, hue: number, gamut: AreaGamut) {
  const width = Math.ceil(canvas.clientWidth / 2)
  const height = Math.ceil(canvas.clientHeight / 2)
  if (width < 2 || height < 2) return
  const wide = gamut === "p3" && matchMedia("(color-gamut: p3)").matches
  const context = canvas.getContext("2d", wide ? { colorSpace: "display-p3" } : undefined)
  if (!context) return
  if (canvas.width !== width) canvas.width = width
  if (canvas.height !== height) canvas.height = height
  const pixels = paintArea(width, height, hue, wide ? "p3" : "srgb")
  context.putImageData(new ImageData(pixels, width, height, wide ? { colorSpace: "display-p3" } : undefined), 0, 0)
}

/** Paints an OKLCH area at `hue` into `canvas` (when it's set), again whenever the hue or the canvas's size changes. */
function useColorAreaCanvas(canvas: RefObject<HTMLCanvasElement | null> | null, hue: number, gamut: AreaGamut) {
  useEffect(() => {
    const element = canvas?.current
    if (!element) return
    let frame = 0
    paint(element, hue, gamut)
    const observer = new ResizeObserver(() => {
      cancelAnimationFrame(frame)
      frame = requestAnimationFrame(() => paint(element, hue, gamut))
    })
    observer.observe(element)
    return () => {
      observer.disconnect()
      cancelAnimationFrame(frame)
    }
  }, [canvas, hue, gamut])
}

export { useColorAreaCanvas }

"use client"

import { colorDistance, formatColor, isInGamut, toGamut, type Color, type ColorGamut } from "@ui-sdk/core/color"
import type { ColorChannel, ColorPickerController, ColorPickerSpace } from "@ui-sdk/react/color-picker"
import { useCallback, useLayoutEffect, useRef } from "react"

/** A key pressed on a thumb: the area's, across `x` and up `y`, or a slider's for `channel`. */
type KeyStep = { key: string; shift: boolean; rtl: boolean } & (
  | { x: ColorChannel; y: ColorChannel }
  | { channel: ColorChannel }
)
/**
 * How an interaction ends: a key, or a pointer lifting where it puts each channel it drags, from 0 to 1 of its range.
 * UI SDK moves at most once a frame, and a pointer that lifts sooner commits a move no render has shown.
 */
type Ending = KeyStep | { release: Partial<Record<ColorChannel, number>> }

type Spec = { index: number; max: number; step: number; scale: number }

// UI SDK's OKLCH channels: only OKLCH reaches past a gamut's edge, since HSV, HSL and sRGB hold sRGB colours.
const oklchChannels: Partial<Record<ColorChannel, Spec>> = {
  lightness: { index: 0, max: 100, step: 0.1, scale: 100 },
  chroma: { index: 1, max: 0.4, step: 0.001, scale: 1 },
  hue: { index: 2, max: 360, step: 1, scale: 1 },
  alpha: { index: 3, max: 100, step: 1, scale: 100 },
}

const decimals = (step: number) => (Number.isInteger(step) ? 0 : (String(step).split(".")[1] ?? "").length)

function snap(value: number, spec: Spec) {
  const steps = Math.round(Number((value / spec.step).toPrecision(15)))
  return Math.min(spec.max, Math.max(0, Number((steps * spec.step).toFixed(decimals(spec.step)))))
}

function read(color: Color, spec: Spec) {
  const coord = spec.index === 3 ? color.alpha : color.coords[spec.index]
  return Number(((coord ?? 0) * spec.scale).toFixed(4))
}

function write(color: Color, spec: Spec, value: number): Color {
  const coord = Math.min(spec.max, Math.max(0, value)) / spec.scale
  if (spec.index === 3) return { ...color, alpha: coord }
  const coords: Color["coords"] = [...color.coords]
  coords[spec.index] = coord
  return { ...color, coords }
}

function placed(color: Color, fractions: Partial<Record<ColorChannel, number>>): Color | null {
  let next = color
  for (const [channel, fraction] of Object.entries(fractions)) {
    const spec = oklchChannels[channel as ColorChannel]
    if (!spec || fraction === undefined) return null
    next = write(next, spec, snap(Math.min(1, Math.max(0, fraction)) * spec.max, spec))
  }
  return next
}

// The step UI SDK takes for a key, applied to the colour the thumbs held before it rather than the one it holds.
function stepped(color: Color, step: KeyStep): Color | null {
  const times = step.shift ? 10 : 1
  const across = step.rtl ? -1 : 1
  if ("channel" in step) {
    const spec = oklchChannels[step.channel]
    if (!spec) return null
    const current = read(color, spec)
    const moves: Record<string, number> = {
      ArrowUp: current + spec.step * times,
      ArrowDown: current - spec.step * times,
      ArrowRight: current + across * spec.step * times,
      ArrowLeft: current - across * spec.step * times,
      PageUp: current + spec.max / 10,
      PageDown: current - spec.max / 10,
      Home: 0,
      End: spec.max,
    }
    const move = moves[step.key]
    return move === undefined ? null : write(color, spec, snap(move, spec))
  }
  const x = oklchChannels[step.x]
  const y = oklchChannels[step.y]
  if (!x || !y) return null
  let [nextX, nextY] = [read(color, x), read(color, y)]
  if (step.key === "ArrowRight" || step.key === "ArrowLeft")
    nextX += (step.key === "ArrowRight" ? across : -across) * x.step * times
  else if (step.key === "ArrowUp" || step.key === "ArrowDown")
    nextY += (step.key === "ArrowUp" ? 1 : -1) * y.step * times
  else if (step.key === "PageUp" || step.key === "PageDown") nextY += ((step.key === "PageUp" ? 1 : -1) * y.max) / 10
  else if (step.key === "Home") nextX = 0
  else if (step.key === "End") nextX = x.max
  else return null
  return write(write(color, x, snap(nextX, x)), y, snap(nextY, y))
}

type HeldColorOptions = {
  color: Color
  space: ColorPickerSpace | undefined
  gamut: ColorGamut | false | undefined
  controller: ColorPickerController
}

/**
 * Keeps the thumbs where a drag or a key left them past the gamut's edge. Ending an interaction, UI SDK moves its
 * colour to the closest one inside, and the thumb jumps back, though the value is that closest colour already.
 * When the colour held before (after a key's step) maps to UI SDK's, this puts it back. Returns where a thumb
 * reports a key, since UI SDK steps and commits a key in one event, with no render between.
 */
function useHeldColor({ color, space, gamut = "srgb", controller }: HeldColorOptions) {
  const held = useRef<Color | null>(null)
  const ending = useRef<Ending | null>(null)
  useLayoutEffect(() => {
    const previous = held.current
    const end = ending.current
    held.current = color
    ending.current = null
    if (!previous || !end || space !== "oklch" || !gamut || !isInGamut(color, gamut)) return
    const candidates = "release" in end ? [previous, placed(previous, end.release)] : [stepped(previous, end)]
    const candidate = candidates.find(
      (option) =>
        option &&
        !isInGamut(option, gamut) &&
        option.alpha === color.alpha &&
        colorDistance(toGamut(option, gamut), color) <= 1e-6,
    )
    if (!candidate) return
    // UI SDK reads a hue of 360 as 0, which would send a hue thumb from one end to the other.
    const [l, c, h] = candidate.coords
    const kept = { ...candidate, coords: [l, c, h !== null && h >= 360 ? 360 - 1e-9 : h] satisfies Color["coords"] }
    // 17 significant digits write a double exactly, so UI SDK reads back the same colour and keeps the value.
    controller.setValue(formatColor(kept, "oklch", { precision: 17 }))
  }, [color, space, gamut, controller])
  // Only the render the ending event causes may use it: one that changed nothing leaves no render behind.
  return useCallback((next: Ending) => {
    ending.current = next
    setTimeout(() => {
      if (ending.current === next) ending.current = null
    })
  }, [])
}

export { useHeldColor }
export type { Ending, KeyStep }

// OKLCH against a screen's gamut, for painting a colour area where every pixel is a colour the picker can hold.
// Matrices from Björn Ottosson's OKLab and CSS Color 4 (linear sRGB to and from linear Display P3); the mapping is
// CSS Color 4's, which UI SDK's toGamut follows, written over plain numbers so a whole area paints in a few ms.

type AreaGamut = "srgb" | "p3"
type Oklch = { l: number; c: number; h: number }
type Linear = [number, number, number]

/** The chroma UI SDK's OKLCH area spans left to right, from 0 to this. */
const areaChromaMax = 0.4

function oklchToLinear(l: number, c: number, h: number, gamut: AreaGamut): Linear {
  const radians = (h * Math.PI) / 180
  const a = c * Math.cos(radians)
  const b = c * Math.sin(radians)
  const long = (l + 0.396_337_777_4 * a + 0.215_803_757_3 * b) ** 3
  const medium = (l - 0.105_561_345_8 * a - 0.063_854_172_8 * b) ** 3
  const short = (l - 0.089_484_177_5 * a - 1.291_485_548 * b) ** 3
  const red = 4.076_741_662_1 * long - 3.307_711_591_3 * medium + 0.230_969_929_2 * short
  const green = -1.268_438_004_6 * long + 2.609_757_401_1 * medium - 0.341_319_396_5 * short
  const blue = -0.004_196_086_3 * long - 0.703_418_614_7 * medium + 1.707_614_701 * short
  if (gamut === "srgb") return [red, green, blue]
  return [
    0.822_462_1 * red + 0.177_538 * green,
    0.033_194_1 * red + 0.966_805_8 * green,
    0.017_082_7 * red + 0.072_397_4 * green + 0.910_519_9 * blue,
  ]
}

function linearToOklab([first, second, third]: Linear, gamut: AreaGamut): Linear {
  const [red, green, blue] =
    gamut === "srgb"
      ? [first, second, third]
      : [
          1.224_940_1 * first - 0.224_940_4 * second,
          -0.042_056_9 * first + 1.042_057_1 * second,
          -0.019_637_6 * first - 0.078_636_1 * second + 1.098_273_5 * third,
        ]
  const long = Math.cbrt(0.412_221_470_8 * red + 0.536_332_536_3 * green + 0.051_445_992_9 * blue)
  const medium = Math.cbrt(0.211_903_498_2 * red + 0.680_699_545_1 * green + 0.107_396_956_6 * blue)
  const short = Math.cbrt(0.088_302_461_9 * red + 0.281_718_837_6 * green + 0.629_978_700_5 * blue)
  return [
    0.210_454_255_3 * long + 0.793_617_785 * medium - 0.004_072_046_8 * short,
    1.977_998_495_1 * long - 2.428_592_205 * medium + 0.450_593_709_9 * short,
    0.025_904_037_1 * long + 0.782_771_766_2 * medium - 0.808_675_766 * short,
  ]
}

const inside = (linear: Linear) => linear.every((channel) => channel >= 0 && channel <= 1)
const clip = (linear: Linear): Linear => [
  Math.min(1, Math.max(0, linear[0])),
  Math.min(1, Math.max(0, linear[1])),
  Math.min(1, Math.max(0, linear[2])),
]

function isOklchInGamut(l: number, c: number, h: number, gamut: AreaGamut = "srgb") {
  return inside(oklchToLinear(l, c, h, gamut))
}

/** The most chroma a lightness and hue reach inside the gamut: the edge of the painted colours on that row. */
function maxChroma(l: number, h: number, gamut: AreaGamut = "srgb") {
  if (l <= 0 || l >= 1) return 0
  if (isOklchInGamut(l, areaChromaMax, h, gamut)) return areaChromaMax
  let low = 0
  let high = areaChromaMax
  for (let step = 0; step < 24; step++) {
    const middle = (low + high) / 2
    if (isOklchInGamut(l, middle, h, gamut)) low = middle
    else high = middle
  }
  return low
}

const jnd = 0.02
const precision = 0.0001

/**
 * CSS Color 4 gamut mapping: lower chroma at the same lightness and hue until clipping what is left moves the
 * colour less than a just-noticeable difference, then clip. Returns the linear channels in the gamut.
 */
function mapToGamut(l: number, c: number, h: number, gamut: AreaGamut = "srgb"): Linear {
  if (l >= 1) return [1, 1, 1]
  if (l <= 0) return [0, 0, 0]
  const origin = oklchToLinear(l, c, h, gamut)
  if (inside(origin)) return origin
  const radians = (h * Math.PI) / 180
  const distance = (linear: Linear, chroma: number) => {
    const [lightness, a, b] = linearToOklab(linear, gamut)
    return Math.hypot(lightness - l, a - chroma * Math.cos(radians), b - chroma * Math.sin(radians))
  }
  let clipped = clip(origin)
  if (distance(clipped, c) < jnd) return clipped
  let low = 0
  let high = c
  let lowInside = true
  while (high - low > precision) {
    const chroma = (low + high) / 2
    const current = oklchToLinear(l, chroma, h, gamut)
    if (lowInside && inside(current)) {
      low = chroma
      continue
    }
    clipped = clip(current)
    const error = distance(clipped, chroma)
    if (error < jnd) {
      if (jnd - error < precision) break
      lowInside = false
      low = chroma
    } else {
      high = chroma
    }
  }
  return clipped
}

function linearToOklch(linear: Linear, gamut: AreaGamut, hue: number): Oklch {
  const [l, a, b] = linearToOklab(linear, gamut)
  const c = Math.hypot(a, b)
  const h = c < 1e-6 ? hue : ((Math.atan2(b, a) * 180) / Math.PI + 360) % 360
  return { l, c, h }
}

/**
 * The colour at a point of the area (`x` across, `y` up, both 0 to 1) at hue `h`: the point itself inside the
 * gamut, and past its edge the colour UI SDK holds there, the CSS gamut-mapped one.
 */
function areaColor(x: number, y: number, h: number, gamut: AreaGamut = "srgb"): Oklch {
  const l = Math.min(1, Math.max(0, y))
  const c = Math.max(0, Math.min(1, x)) * areaChromaMax
  if (isOklchInGamut(l, c, h, gamut)) return { l, c, h }
  return linearToOklch(mapToGamut(l, c, h, gamut), gamut, h)
}

/** Where a colour sits in the area, as UI SDK places its thumb: chroma across, lightness up. */
function areaPoint({ l, c }: Oklch) {
  return { x: Math.min(1, c / areaChromaMax), y: Math.min(1, Math.max(0, l)) }
}

const encode = (linear: number) => {
  const value = Math.min(1, Math.max(0, linear))
  return Math.round(255 * (value <= 0.003_130_8 ? 12.92 * value : 1.055 * value ** (1 / 2.4) - 0.055))
}

// Past the edge the mapped colour changes slowly along a row, so it is worked out every few columns and blended
// in between: a mapping is a dozen conversions, and an area holds tens of thousands of pixels.
const mappedStride = 4

/**
 * RGBA pixels for an area `width` by `height` at hue `h`, top row first with lightness 1 at the top, every pixel
 * past the gamut's edge painted as the colour the picker holds there. Both gamuts share sRGB's transfer curve, so
 * the bytes go to a canvas in that colour space.
 */
function paintArea(width: number, height: number, h: number, gamut: AreaGamut = "srgb") {
  const pixels = new Uint8ClampedArray(width * height * 4)
  const chromaAt = (column: number) => (width === 1 ? 0 : column / (width - 1)) * areaChromaMax
  const write = (index: number, [red, green, blue]: Linear) => {
    pixels[index] = encode(red)
    pixels[index + 1] = encode(green)
    pixels[index + 2] = encode(blue)
    pixels[index + 3] = 255
  }
  for (let row = 0; row < height; row++) {
    const l = height === 1 ? 1 : 1 - row / (height - 1)
    const edge = maxChroma(l, h, gamut)
    const offset = row * width * 4
    let column = 0
    for (; column < width && chromaAt(column) <= edge; column++)
      write(offset + column * 4, oklchToLinear(l, chromaAt(column), h, gamut))
    let previous = column
    let before = column < width ? mapToGamut(l, chromaAt(column), h, gamut) : undefined
    if (before) write(offset + column * 4, before)
    while (before && previous < width - 1) {
      const next = Math.min(width - 1, previous + mappedStride)
      const after = mapToGamut(l, chromaAt(next), h, gamut)
      for (let between = previous + 1; between <= next; between++) {
        const t = (between - previous) / (next - previous)
        write(offset + between * 4, [
          before[0] + (after[0] - before[0]) * t,
          before[1] + (after[1] - before[1]) * t,
          before[2] + (after[2] - before[2]) * t,
        ])
      }
      previous = next
      before = after
    }
  }
  return pixels
}

